#include "qa/ValidationRegistry.hpp"
#include <algorithm>
namespace elysium::qa { bool ValidationRegistry::addFamily(TestFamily f){if(f.name.empty()||f.ownerPackage.empty()||families_.contains(f.name))return false;families_.emplace(f.name,std::move(f));return true;} bool ValidationRegistry::addRegression(Regression r){if(r.name.empty()||r.ownerPackage.empty()||r.family.empty()||regressions_.contains(r.name))return false;regressions_.emplace(r.name,std::move(r));return true;} std::vector<TestFamily> ValidationRegistry::select(const std::set<std::string>& tags)const{std::vector<TestFamily>o;for(auto&[n,f]:families_){bool ok=tags.empty();for(auto&t:tags)ok|=f.tags.contains(t);if(ok)o.push_back(f);}return o;} bool ValidationRegistry::hasRegression(const std::string&n)const{return regressions_.contains(n);} std::vector<AuditIssue> ValidationRegistry::audit()const{std::vector<AuditIssue>o;for(auto&[n,r]:regressions_)if(!families_.contains(r.family))o.push_back({"missing_family",n});for(auto&req:requiredForeverRegressions())if(!regressions_.contains(req))o.push_back({"missing_forever_regression",req});return o;} std::vector<std::string> requiredForeverRegressions(){return {"sealed_cavity_internals","supported_worker_equality","checksum_rejection","entt_include_leakage","reflection_reentry_guard","player_placed_ore_exploit","claim_destruction_not_world_erase","untouched_planet_zero_save"};} }
